from pathlib import Path
import json,math
R=Path(__file__).resolve().parents[2];O=R/'cad/fullsize/exports';bom=json.loads((O/'bom.json').read_text())
steel=sum(r['quantity']*r['unit_mass_kg'] for r in bom if r['material'].startswith('S235'))
lines=[('Structural steel stock',math.ceil(steel*80),math.ceil(steel*140),f'{steel:.1f} kg idealized structural steel × assumed INR80–140/kg; not a supplier quote'),('Roof materials, forming and sealed drainage',9000,16000,'6.72 m² per skin; profile, seams, fasteners and gutter remain supplier design'),('Frame cutting, drilling, welding and jigs',15000,25000,'One-off first-article allowance; no local quote'),('Corrosion protection and finishing',5000,9000,'Surface preparation and coating allowance; specification not approved'),('Bench and removable screens',8000,14000,'Materials, finish and assembly allowance'),('Outdoor electronics, fan and protected low-voltage power',6000,12000,'Qualified outdoor substitutions and installation unresolved'),('Foundations, anchors and site preparation',10000,20000,'Provisional sum only; soil and anchor design can change this substantially'),('Transport, erection and installation',8000,15000,'Access/lifting/distance not surveyed'),('Engineering review and first-article inspection',8000,15000,'Planning allowance, not a service offer')]
items=[dict(item=a,estimate_low=b,estimate_high=c,notes=d) for a,b,c,d in lines]
low=sum(x['estimate_low'] for x in items);high=sum(x['estimate_high'] for x in items);items.append(dict(item='Contingency / tax reconciliation allowance',estimate_low=math.ceil(low*.15),estimate_high=math.ceil(high*.15),notes='15% planning buffer; final quote must state applicable taxes separately'))
record=dict(date='2026-10-12',currency='INR',basis='FS-01 first-article planning allowances, NOT supplier quotations',structural_steel_mass_kg=round(steel,2),items=items,total_low=sum(x['estimate_low'] for x in items),total_high=sum(x['estimate_high'] for x in items),cost_target='NOT DEMONSTRATED: substantially above prior equipment-only AC reference; installed AC benchmark remains missing',exclusions='No procurement or quoted installation; actual site changes, approvals and abnormal ground conditions can exceed these allowances')
(O/'cost-screening.json').write_text(json.dumps(record,indent=2))
p=R/'research/costs.json';data=json.loads(p.read_text());data.setdefault('superseded_concept_full_size_2026_10_11',data['full_size']);data['full_size']=items;data['full_size_basis']=record['basis'];data['full_size_revision_date']=record['date'];p.write_text(json.dumps(data,indent=2)+'\n');print(record['total_low'],record['total_high'])
